#!/usr/bin/env python3
"""Actual pinned SDK string leaves for ATTRIB pointer-boundary comparisons."""
import argparse,hashlib,json,subprocess
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--out',type=Path,required=True);a=p.parse_args();root=Path(__file__).resolve().parents[1];sdk=root/'.cache/emsdk/upstream/emscripten';out=a.out.resolve();assert not out.exists();out.mkdir(parents=True);source=root/'scripts/standalone-sdk-directory-probe.c'
cmd=[str(sdk/'emcc'),'-O2','-g','-sMEMORY64=1','-sMODULARIZE=1','-sEXPORT_ES6=1','-sENVIRONMENT=node','-sALLOW_MEMORY_GROWTH=1','-sEXPORTED_RUNTIME_METHODS=HEAPU8','-sEXPORTED_FUNCTIONS='+json.dumps(['_'+v for v in ['strcmp','strcpy','strlen','malloc','free']]),'--no-entry',str(source),'-I'+str(sdk/'system/lib/libc/musl/src/dirent'),'-o',str(out/'reference.mjs')];r=subprocess.run(cmd,capture_output=True,text=True);(out/'build.log').write_text(r.stdout+r.stderr);assert r.returncode==0,r.stderr;(out/'command.json').write_text(json.dumps(cmd,indent=2)+'\n');inputs=[Path(__file__).resolve(),source,sdk/'emcc',root/'.cache/emsdk/upstream/bin/clang',sdk/'cache/sysroot/include/string.h',sdk/'cache/sysroot/include/bits/alltypes.h'];inputs.extend((sdk/'system/lib/libc/musl/src/string').glob('*.[ch]'));sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();(out/'receipt.json').write_text(json.dumps({'profile':'Original pinned SDK O2 MEMORY64 libc string functions, no body replacements','sourceSha256':{str(p):sha(p)for p in inputs},'artifactSha256':{p.name:sha(p)for p in [out/'reference.mjs',out/'reference.wasm']}},indent=2)+'\n');print(out)
